import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest cases -------------------------------------------
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(output).toEqual({ results: [{ premium: 5 }] });
  });
  it("single plain potion for a new customer → base 40 G + 4 G first insurance + 5 G fee = 49 G", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });

    expect(output).toEqual({ results: [{ premium: 49 }] });
  });
  it("single plain sword for a new customer → base 100 G + 10 G first insurance + 5 G fee = 115 G", () => {
    const output = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(output).toEqual({ results: [{ premium: 115 }] });
  });
  it.todo("single plain amulet for a new customer → base 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("single plain staff for a new customer → base 80 G + 8 G first insurance + 5 G fee = 93 G");

  // --- Components and the building block -------------------------------
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers -----------------------------------------
  it.todo("cursed sword adds a 50 % surcharge on the item's base premium (100 G → 150 G base portion)");
  it.todo("sword with enchantment 5 adds a 30 % high-enchantment surcharge (exactly at the threshold)");
  it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 gets both surcharges (50 % + 30 %)");

  // --- Policy-wide modifiers -------------------------------------------
  it.todo("customer with exactly 2 years with MHPCO gets the 20 % loyalty discount");
  it.todo("customer with 1 year with MHPCO gets no loyalty discount");
  it.todo("the second quote in a scenario gets the 15 % follow-up contract discount");
  it.todo("the first insurance surcharge of 10 % applies to every quote, including follow-up contracts");

  // --- Modifier scope on multi-item policies ---------------------------
  it.todo("policy with a cursed sword (100 G) and a plain amulet (60 G) → 160 G base + 50 G curse = 210 G before further modifiers and fee");

  // --- Rounding ---------------------------------------------------------
  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up, in MHPCO's favor)");
  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down, in MHPCO's favor)");

  // --- Integration examples --------------------------------------------
  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");

  // --- Claim: standard reimbursement -----------------------------------
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (no enchantment/material clause)");

  // --- Claim: special clauses ------------------------------------------
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over full reimbursement)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (threshold applies)");

  // --- Claim: deductible per damage event ------------------------------
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");

  // --- Claim: insurance sum and cap ------------------------------------
  it.todo("policy with a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("policy with two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("policy with a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("policy with a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G (block discount does not lower the insurance sum)");
  it.todo("sword policy (cap 2000 G), two successive claims of 1500 G → first payout 1400 G with remainingCap 600 G, second payout 600 G with remainingCap 0 G");

  // --- Claim: multiple items of the same type --------------------------
  it.todo("policy with two swords, a dragon attack damaging both → each damage entry gets its own deductible");
  it.todo("damages contain more entries of a type than the policy covers (two sword damages, one sword insured) → error");

  // --- Errors -----------------------------------------------------------
  it.todo("quote with an unknown item type (e.g. broomstick) → error");
  it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
  it.todo("claim references a damage entry with an unknown item type → error");
  it.todo("claim contains a damage entry with amount -200 → error");

  // --- CLI --------------------------------------------------------------
  it.todo("CLI reads the schema example scenario from stdin and writes {results: [{premium}, {payout, remainingCap}]} to stdout");
  it.todo("CLI exits with a non-zero status code and writes an error description to stderr for an unknown item type, writing no results to stdout");
});

