export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioOutput {
  results: QuoteResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  potion: 40,
  sword: 100,
  amulet: 60,
  staff: 80,
};

/**
 * Premiums round up (the MHPCO's favour). Binary drift is cleared first so a
 * whole amount like 115.00000000000001 does not creep up to 116.
 */
const ROUNDING_PRECISION = 6;

function roundUpPremium(amount: number): number {
  return Math.ceil(Number(amount.toFixed(ROUNDING_PRECISION)));
}

function basePremium(item: Item): number {
  return BASE_PREMIUMS[item.type] ?? 0;
}

function quotePremium(step: QuoteStep): number {
  const base = step.items.reduce((sum, item) => sum + basePremium(item), 0);
  return roundUpPremium(base * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step) })) };
}

