export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioOutput {
  results: QuoteResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

/** The MHPCO price list for main items, in the order the tariff publishes it. */
const MAIN_ITEM_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

/** Components (runes, moonstones, ...) all carry the same per-piece premium. */
const COMPONENT_PREMIUM = 25;
const COMPONENT_TYPES = ["rune"];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const ROUNDING_PRECISION = 6;

/**
 * Premiums round up (the MHPCO's favour). Binary drift is cleared first so a
 * whole amount like 115.00000000000001 does not creep up to 116.
 */
function roundUpPremium(amount: number): number {
  return Math.ceil(Number(amount.toFixed(ROUNDING_PRECISION)));
}

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

function basePremium(item: Item): number {
  return MAIN_ITEM_PREMIUMS[item.type] ?? 0;
}

/** A building block of exactly 3 alike components is offered at a flat rate. */
function componentsBasePremium(components: Item[]): number {
  if (components.length === BLOCK_SIZE) return BLOCK_PREMIUM;
  return components.length * COMPONENT_PREMIUM;
}

function quoteBasePremium(items: Item[]): number {
  const mainItems = items.filter((item) => !isComponent(item));
  const components = items.filter(isComponent);
  const mainItemsBase = mainItems.reduce((sum, item) => sum + basePremium(item), 0);
  return mainItemsBase + componentsBasePremium(components);
}

function quotePremium(step: QuoteStep): number {
  const base = quoteBasePremium(step.items);
  return roundUpPremium(base * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step) })) };
}

