    applies: (customer) => customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
    rate: -LOYALTY_DISCOUNT,
  },
];

function policyModifierRate(customer: Customer): number {
  return POLICY_MODIFIERS.filter(({ applies }) => applies(customer)).reduce(
    (total, { rate }) => total + rate,
    0,
  );
}

function quotePremium(step: QuoteStep, customer: Customer): number {
  const policyBase = policyBasePremium(step.items);
  const policyModifiers = policyBase * policyModifierRate(customer);
  return roundUpPremium(
    policyBase + itemSurcharges(step.items) + policyModifiers + PROCESSING_FEE,
  );
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return {
    results: scenario.steps.map((step) => ({
      premium: quotePremium(step, scenario.customer),
    })),
  };
}

