  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
};
const COMPONENT_INSURANCE_VALUE = 250;

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

/** Components (runes, moonstones, ...) all carry the same per-piece premium. */
const COMPONENT_PREMIUM = 25;
const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const ROUNDING_PRECISION = 6;

/**
 * Premiums round up (the MHPCO's favour). Binary drift is cleared first so a
 * whole amount like 115.00000000000001 does not creep up to 116.
 */
function roundUpPremium(amount: number): number {
  return Math.ceil(Number(amount.toFixed(ROUNDING_PRECISION)));
}

