function roundDownPayout(amount: number): number {
  return Math.floor(Number(amount.toFixed(ROUNDING_PRECISION)));
}

function claimPayout(step: ClaimStep, policyItems: Item[]): number {
  return step.incident.damages.reduce(
    (total, damage) => total + Math.max(0, damage.amount - DEDUCTIBLE),
